import os,sys
R=sys.argv[1]+'/layout'
NS='xmlns:android="http://schemas.android.com/apk/res/android"'
SH='android:shadowColor="#40103060" android:shadowDy="1" android:shadowRadius="4"'
def tv(id,size,color='#FFFFFF',bold=False,extra='',shadow=True,w='wrap_content',h='wrap_content'):
    return f'<TextView android:id="@+id/{id}" android:layout_width="{w}" android:layout_height="{h}" android:textSize="{size}sp" android:textColor="{color}" {"android:textStyle=\"bold\"" if bold else ""} android:maxLines="1" android:ellipsize="end" android:includeFontPadding="false" {SH if shadow else ""} {extra}/>'
def img(id,size,extra=''):
    return f'<ImageView android:id="@+id/{id}" android:layout_width="{size}dp" android:layout_height="{size}dp" android:scaleType="fitCenter" {extra}/>'
def root(inner,bg='w_bg',deco=True,pad=12):
    d=f'<ImageView android:id="@+id/deco" android:layout_width="110dp" android:layout_height="55dp" android:layout_gravity="bottom|end" android:src="@drawable/w_deco_cloud" android:alpha="0.75" android:scaleType="fitEnd"/>' if deco else ''
    return f'<?xml version="1.0" encoding="utf-8"?>\n<FrameLayout {NS} android:id="@+id/root" android:layout_width="match_parent" android:layout_height="match_parent" android:background="@drawable/{bg}">{d}<LinearLayout android:layout_width="match_parent" android:layout_height="match_parent" android:orientation="vertical" android:padding="{pad}dp">{inner}</LinearLayout></FrameLayout>'
def locrow(size=12.5):
    return f'<LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:gravity="center_vertical" android:orientation="horizontal"><ImageView android:id="@+id/locIcon" android:layout_width="13dp" android:layout_height="13dp" android:src="@drawable/ic_w_nav"/>{tv("loc",size,bold=True,extra="android:layout_marginStart=\"5dp\"",w="0dp")[:-2].replace("android:layout_width=\"0dp\"","android:layout_width=\"0dp\" android:layout_weight=\"1\"")}/></LinearLayout>'
def hours(n,ink='#10233F'):
    cells=''
    for i in range(n):
        sep='' if i==0 else '<ImageView android:layout_width="1dp" android:layout_height="match_parent" android:layout_marginTop="4dp" android:layout_marginBottom="4dp" android:src="@drawable/w_vline" android:scaleType="fitXY"/>'
        cells+=sep+f'<LinearLayout android:layout_width="0dp" android:layout_height="match_parent" android:layout_weight="1" android:gravity="center" android:orientation="vertical">{tv(f"ht{i}",12.5,"#5D6E86",shadow=False)}{img(f"hi{i}",30,"android:layout_marginTop=\"3dp\"")}{tv(f"hv{i}",16,ink,True,"android:layout_marginTop=\"2dp\"",shadow=False)}{tv(f"hp{i}",12,"#1E74E8",True,"android:layout_marginTop=\"2dp\"",shadow=False)}</LinearLayout>'
    return cells
def days(n):
    rows=''
    for i in range(n):
        rows+=f'<LinearLayout android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:gravity="center_vertical" android:orientation="horizontal">{tv(f"dl{i}",15.5,"#10233F",True,"",False,w="40dp")}{img(f"di{i}",30)}{tv(f"dp{i}",14,"#1E74E8",True,"android:gravity=\"center\"",False,w="46dp")}{tv(f"dn{i}",15.5,"#10233F",True,"android:gravity=\"end\"",False,w="36dp")}<ImageView android:id="@+id/db{i}" android:layout_width="0dp" android:layout_height="8dp" android:layout_weight="1" android:layout_marginStart="8dp" android:layout_marginEnd="8dp" android:scaleType="fitXY"/>{tv(f"dx{i}",15.5,"#10233F",True,"android:gravity=\"end\"",False,w="36dp")}</LinearLayout>'
    return rows
L={}
L['w_1x1']=root(f'<LinearLayout android:layout_width="match_parent" android:layout_height="match_parent" android:gravity="center" android:orientation="vertical">{img("ic",40)}{tv("tp",22,bold=True)}</LinearLayout>',pad=6,deco=False)
L['w_2x1']=root(f'<LinearLayout android:layout_width="match_parent" android:layout_height="match_parent" android:gravity="center_vertical" android:orientation="horizontal">{img("ic",54)}<LinearLayout android:layout_width="wrap_content" android:layout_height="wrap_content" android:layout_marginStart="8dp" android:orientation="vertical">{tv("tp",30,bold=True)}{tv("hilo",15,extra="android:layout_marginTop=\"2dp\"")}</LinearLayout></LinearLayout>',pad=10)
L['w_2x2']=root(locrow(14)+f'<LinearLayout android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:gravity="center_vertical" android:orientation="horizontal">{tv("tp",44,bold=True,w="0dp").replace("android:layout_width=\"0dp\"","android:layout_width=\"0dp\" android:layout_weight=\"1\"")}{img("ic",58)}</LinearLayout>{tv("cond",17,bold=True)}{tv("hilo",13.5,extra="android:layout_marginTop=\"3dp\"")}{tv("pop",13.5,extra="android:layout_marginTop=\"2dp\"")}',pad=14)
L['w_4x1']=root(f'<LinearLayout android:layout_width="match_parent" android:layout_height="match_parent" android:gravity="center_vertical" android:orientation="horizontal">{img("ic",52)}{tv("tp",36,bold=True,extra="android:layout_marginStart=\"8dp\"")}<ImageView android:layout_width="1dp" android:layout_height="34dp" android:layout_marginStart="12dp" android:layout_marginEnd="12dp" android:src="@drawable/w_divider" android:scaleType="fitXY"/><LinearLayout android:layout_width="0dp" android:layout_height="wrap_content" android:layout_weight="1" android:orientation="vertical">{locrow(14.5)}{tv("sum",14,extra="android:layout_marginTop=\"4dp\"")}</LinearLayout></LinearLayout>',pad=10)
top4x2=f'<LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:gravity="center_vertical" android:orientation="horizontal" android:paddingStart="4dp" android:paddingEnd="4dp">{img("ic",46)}{tv("tp",34,bold=True,extra="android:layout_marginStart=\"6dp\"")}<LinearLayout android:layout_width="0dp" android:layout_height="wrap_content" android:layout_weight="1" android:layout_marginStart="8dp" android:orientation="vertical">{locrow(14.5)}{tv("sum",13.5,extra="android:layout_marginTop=\"3dp\"")}</LinearLayout>{tv("upd",11.5,extra="android:layout_gravity=\"top\"")}</LinearLayout>'
L['w_4x2']=root(top4x2+f'<LinearLayout android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:layout_marginTop="8dp" android:background="@drawable/w_panel" android:orientation="horizontal" android:padding="6dp">{hours(6)}</LinearLayout>',pad=10)
top4x4=f'<LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:gravity="center_vertical" android:orientation="horizontal" android:paddingStart="4dp" android:paddingEnd="4dp">{img("ic",60)}{tv("tp",44,bold=True,extra="android:layout_marginStart=\"6dp\"")}<LinearLayout android:layout_width="0dp" android:layout_height="wrap_content" android:layout_weight="1" android:layout_marginStart="10dp" android:orientation="vertical">{locrow(15)}{tv("sum",14,extra="android:layout_marginTop=\"4dp\"")}{tv("sum2",13.5,extra="android:layout_marginTop=\"3dp\"")}</LinearLayout></LinearLayout>'
L['w_4x4']=root(top4x4+f'<LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:layout_marginTop="8dp" android:background="@drawable/w_panel" android:orientation="horizontal" android:paddingTop="8dp" android:paddingBottom="8dp" android:paddingStart="4dp" android:paddingEnd="4dp">{hours(6)}</LinearLayout><LinearLayout android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:layout_marginTop="8dp" android:background="@drawable/w_panel" android:orientation="vertical" android:paddingStart="14dp" android:paddingEnd="14dp" android:paddingTop="4dp" android:paddingBottom="4dp">{days(5)}</LinearLayout><LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:layout_marginTop="6dp" android:gravity="center_vertical" android:orientation="horizontal" android:paddingStart="6dp" android:paddingEnd="2dp">{tv("upd",12,"#E61E4FA0",shadow=False,w="0dp").replace("android:layout_width=\"0dp\"","android:layout_width=\"0dp\" android:layout_weight=\"1\"")}<ImageView android:id="@+id/refresh" android:layout_width="26dp" android:layout_height="26dp" android:padding="4dp" android:src="@drawable/ic_w_refresh"/></LinearLayout>',pad=10)
# 비교 2x2 (남색)
rows=''.join(f'<LinearLayout android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:gravity="center_vertical" android:orientation="horizontal">{tv(f"kn{i}",15,bold=True,shadow=False,w="0dp").replace("android:layout_width=\"0dp\"","android:layout_width=\"0dp\" android:layout_weight=\"1\"")}{tv(f"kv{i}",15,bold=True,shadow=False)}</LinearLayout>' for i in range(4))
L['c_2x2']=root(locrow(14)+f'<LinearLayout android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:layout_marginTop="8dp" android:background="@drawable/w_panel_dark" android:orientation="vertical" android:paddingStart="12dp" android:paddingEnd="12dp" android:paddingTop="6dp" android:paddingBottom="6dp">{tv("ktitle",12,"#CCFFFFFF",shadow=False)}{rows}</LinearLayout><LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:layout_marginTop="6dp" android:gravity="center_vertical" android:orientation="horizontal"><ImageView android:layout_width="12dp" android:layout_height="12dp" android:src="@drawable/ic_w_bars"/>{tv("kfoot",12,"#E6FFFFFF",shadow=False,extra="android:layout_marginStart=\"6dp\"")}</LinearLayout>',bg='w_bg_navy',deco=False,pad=14)
def cmpl(fs,ic,wc,wx,wm,wr,locsp,headsp,dot,pp=14,rp=10,tic=52,ttp=40,csp=14,hsp=11):
    crow=''.join(f'<LinearLayout android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:gravity="center_vertical" android:orientation="horizontal">{tv(f"cd{i}",dot,"#1E6FE6",shadow=False).replace("android:maxLines","android:text=\"●\" android:maxLines")}{tv(f"cn{i}",fs,"#10233F",True,"android:layout_marginStart=\"8dp\"",False,w="0dp").replace("android:layout_width=\"0dp\"","android:layout_width=\"0dp\" android:layout_weight=\"1\"")}{img(f"ci{i}",ic)}{tv(f"cc{i}",fs,"#10233F",True,"android:gravity=\"end\"",False,w=f"{wc}dp")}{tv(f"cx{i}",fs,"#10233F",True,"android:gravity=\"end\"",False,w=f"{wx}dp")}{tv(f"cm{i}",fs,"#5D6E86",True,"android:gravity=\"end\"",False,w=f"{wm}dp")}{tv(f"cr{i}",fs,"#1E74E8",True,"android:gravity=\"end\"",False,w=f"{wr}dp")}</LinearLayout>' for i in range(5))
    hdr=f'<LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="horizontal" android:paddingTop="4dp"><TextView android:layout_width="0dp" android:layout_height="wrap_content" android:layout_weight="1"/>' + ''.join(f'<TextView android:layout_width="{w}dp" android:layout_height="wrap_content" android:gravity="end" android:text="{t}" android:textSize="{hsp}sp" android:textColor="#8C9BB0" android:includeFontPadding="false"/>' for t,w in (("현재",wc),("최고",wx),("최저",wm),("강수",wr))) + '</LinearLayout>'
    top=f'<LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:gravity="center_vertical" android:orientation="horizontal" android:paddingStart="4dp" android:paddingEnd="4dp">{img("ic",tic)}{tv("tp",ttp,bold=True,extra="android:layout_marginStart=\"6dp\"")}<LinearLayout android:layout_width="0dp" android:layout_height="wrap_content" android:layout_weight="1" android:layout_marginStart="10dp" android:orientation="vertical">{locrow(locsp)}{tv("cond",csp,extra="android:layout_marginTop=\"4dp\"")}</LinearLayout></LinearLayout>'
    return root(top+f'<LinearLayout android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:layout_marginTop="8dp" android:background="@drawable/w_panel" android:orientation="vertical" android:paddingStart="{pp}dp" android:paddingEnd="{pp}dp" android:paddingTop="4dp" android:paddingBottom="4dp">{hdr}{crow}</LinearLayout>',pad=rp)
L['c_4x2']=cmpl(13.5,22,40,38,34,50,14,12,11,tic=40,ttp=30,csp=12.5,hsp=10)
L['c_4x4']=cmpl(15,26,42,42,36,52,16,13,12,pp=10,rp=10,tic=64,ttp=48,csp=15,hsp=11)
L['w_loading']=root(f'<LinearLayout android:layout_width="match_parent" android:layout_height="match_parent" android:gravity="center" android:orientation="vertical">{tv("msg",13,extra="android:gravity=\"center\"")}</LinearLayout>',pad=10)
for k,v in L.items(): open(f'{R}/{k}.xml','w').write(v)
print(list(L))
